	mu  sync.Mutex
	now time.Time
}

func newFakeClock(start time.Time) *fakeClock { return &fakeClock{now: start} }

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func TestNewValidation(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	tests := []struct {
		name    string
		rate    float64
		burst   int
		clock   Clock
		wantErr error
	}{
		{"zero rate", 0, 1, clk, ErrNonPositiveRate},
		{"negative rate", -1, 1, clk, ErrNonPositiveRate},
		{"zero burst", 1, 0, clk, ErrNonPositiveBurst},
		{"negative burst", 1, -5, clk, ErrNonPositiveBurst},
		{"nil clock", 1, 1, nil, ErrNilClock},
		{"valid", 1, 1, clk, nil},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			l, err := New(tc.rate, tc.burst, tc.clock)
			if !errors.Is(err, tc.wantErr) {
				t.Fatalf("New() error = %v, want %v", err, tc.wantErr)
			}
			if tc.wantErr == nil && l == nil {
				t.Fatal("New() returned nil limiter with nil error")
			}
		})
	}
