			name: "fractional refill accumulates",
			rate: 2, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 1, false},
				{250 * time.Millisecond, 1, false}, // 0.5 tokens
